const tags = [target.kind];
if (target.os) tags.push(target.os);
if (target.arch) tags.push(target.arch);
const user = (target.username || '').toLowerCase();
if (user.includes('system') || user === 'root') tags.push('high-priv');
const updated = sliver.tags.add(tags.join(','));
sliver.log('Tags:', updated.join(', '));

